export function improveLocalizedQualityContent(locale: SupportedLocale, content: LocaleDictionary["calculators"]): LocaleDictionary["calculators"] {
  const additions = followups[locale] ?? {};
  const batchNotes = batchExampleNotes[locale] ?? {};
  const nextBatchNotes = nextBatchExampleNotes[locale] ?? {};
  const reviewedBatchNotes = reviewedBatchExampleNotes[locale] ?? {};
  const secondReviewedBatchNotes = secondReviewedBatchExampleNotes[locale] ?? {};
  const thirdReviewedBatchNotes = thirdReviewedBatchExampleNotes[locale] ?? {};
  const fourthReviewedBatchNotes = fourthReviewedBatchExampleNotes[locale] ?? {};
  const fifthReviewedBatchNotes = fifthReviewedBatchExampleNotes[locale] ?? {};
  const sixthReviewedBatchNotes = sixthReviewedBatchExampleNotes[locale] ?? {};
  const seventhReviewedBatchNotes = seventhReviewedBatchExampleNotes[locale] ?? {};
  const eighthReviewedBatchNotes = eighthReviewedBatchExampleNotes[locale] ?? {};
  return Object.fromEntries(Object.entries(content).map(([slug, page]) => {
    const addition = additions[slug] ?? {};
    const exampleNotes = [addition.exampleNote ?? batchNotes[slug], nextBatchNotes[slug], slug === "ratio" ? undefined : reviewedBatchNotes[slug], secondReviewedBatchNotes[slug], thirdReviewedBatchNotes[slug], fourthReviewedBatchNotes[slug], fifthReviewedBatchNotes[slug], sixthReviewedBatchNotes[slug], seventhReviewedBatchNotes[slug], eighthReviewedBatchNotes[slug]].filter((note): note is string => Boolean(note));
    const exampleNote = exampleNotes.join(" ");
    const ratioInterpretation = slug === "ratio" ? reviewedBatchNotes[slug] : undefined;
    if (!page || (!addition.description && !exampleNote && !ratioInterpretation)) return [slug, page];
    const updated: LocalizedCalculatorContent = {
      ...page,
      ...((addition.description || ratioInterpretation) ? { description: [page.description, addition.description, ratioInterpretation].filter(Boolean).join(" ") } : {}),
      ...(exampleNote ? { example: { ...page.example, answer: `${page.example.answer} ${exampleNote}` } } : {}),
    };
    return [slug, updated];
  })) as LocaleDictionary["calculators"];
}
